from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove any spaces from the input string
    groups = []
    stack = []

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)  # Step 2: Identify the starting index of each opening parenthesis
        elif char == ')':
            if stack:
                start = stack.pop()
                groups.append(paren_string[start:i+1])  # Step 3 & 4: Identify the corresponding closing parenthesis and extract the group
            else:
                raise ValueError("Unbalanced parentheses")

    if stack:
        raise ValueError("Unbalanced parentheses")

    return groups  # Step 5: Return the list of extracted groups

